import java.io.File;
import java.lang.reflect.*;
import java.util.*;
import javax.imageio.ImageIO;
import javax.microedition.lcdui.*;
import org.microemu.app.Headless;
import org.microemu.app.Common;
import org.microemu.app.util.DeviceEntry;
import org.microemu.device.j2se.J2SEDevice;
import org.microemu.device.j2se.J2SEDeviceDisplay;
import org.microemu.device.DeviceFactory;
import org.microemu.device.impl.Rectangle;
import org.microemu.MIDletBridge;

/** Exercises an unmodified Java ME JAR in isolated RMS memory. Failures are logged separately. */
public final class OriginalAudit {
    static Class<?> canvas; static Object menu; static int h; static String out; static Display display;
    interface Check {boolean ok() throws Exception;}
    static void waitFor(Check c,String m) throws Exception {long t=System.currentTimeMillis()+30000;while(System.currentTimeMillis()<t){if(c.ok())return;Thread.sleep(100);}throw new AssertionError("Timeout: "+m);}
    static Object get(Object o,String field) throws Exception {Class<?> c=o.getClass();while(c!=null){try{Field f=c.getDeclaredField(field);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException e){c=c.getSuperclass();}}throw new NoSuchFieldException(field);}
    static Object cur() throws Exception{return canvas.getField("curScr").get(null);}
    static Object dlg() throws Exception{return canvas.getField("currentDialog").get(null);}
    static void close() throws Exception{canvas.getMethod("endDlg").invoke(null);}
    static void act(Object o,String side) throws Exception {Object cmd=o.getClass().getField(side).get(o);if(cmd==null)throw new AssertionError("Missing "+side);Object action=cmd.getClass().getField("action").get(cmd);Method m=action.getClass().getMethod("perform");m.setAccessible(true);m.invoke(action);}
    static void click(int n) throws Exception{int top=(h-(6*36+22))/2;menu.getClass().getMethod("onPointerReleased",int.class,int.class,int.class).invoke(menu,240,top+n*36+5,0);}
    static void snapshot(String n) throws Exception {Thread.sleep(400);java.awt.image.BufferedImage im=new java.awt.image.BufferedImage(480,800,java.awt.image.BufferedImage.TYPE_INT_RGB);((J2SEDeviceDisplay)DeviceFactory.getDevice().getDeviceDisplay()).paintDisplayable(im.getGraphics(),0,0,480,800);ImageIO.write(im,"png",new File(out,n+".png"));}
    static String info(Object d) throws Exception {String[] lines=(String[])get(d,"info");StringBuilder s=new StringBuilder();if(lines!=null)for(String x:lines)s.append(x).append(' ');return s.toString();}
    static void input(String text) throws Exception {Object d=dlg();if(d==null || !d.getClass().getName().equals("model.InputDlg"))throw new AssertionError("Expected input dialog"); Object f=d.getClass().getField("tfInput").get(d);f.getClass().getMethod("setText",String.class).invoke(f,text);act(d,"center");}
    public static void main(String[] a){try{run(a);System.out.println("ORIGINAL_AUDIT_PASS");System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
    static void run(String[] a) throws Exception {
        out=a[1];Headless headless=new Headless();Common emu=(Common)get(headless,"emulator");ArrayList<String> args=new ArrayList<String>();args.add("--rms");args.add("memory");args.add(a[0]);emu.initParams(args,new DeviceEntry("Default device",null,"org/microemu/device/default/device.xml",true,false),J2SEDevice.class);J2SEDeviceDisplay dd=(J2SEDeviceDisplay)DeviceFactory.getDevice().getDeviceDisplay();dd.setDisplayRectangle(new Rectangle(0,0,480,800));dd.setDisplayPaintable(new Rectangle(0,0,480,800));emu.initMIDlet(true);Object midlet=MIDletBridge.getCurrentMIDlet();if(midlet==null)throw new AssertionError("No MIDlet");display=Display.getDisplay((javax.microedition.midlet.MIDlet)midlet);canvas=midlet.getClass().getClassLoader().loadClass("coreLG.CCanvas");waitFor(()->cur()!=null && cur().getClass().getName().equals("screen.MainMenuScr"),"main menu");menu=cur();h=((Integer)canvas.getField("hieght").get(null));snapshot("01-main");
        try { click(0);waitFor(()->dlg()!=null && dlg().getClass().getName().equals("model.InputDlg"),"login input");snapshot("02-login-name");input("TestUser");waitFor(()->dlg()!=null && dlg().getClass().getName().equals("model.MsgDlg"),"login guard");System.out.println("login guard: "+info(dlg()));snapshot("03-login-no-character");close(); } catch(Throwable e) { System.out.println("LOGIN_FAILED: "+e);e.printStackTrace();if(dlg()!=null)close(); }
        try { click(1);waitFor(()->dlg()!=null && dlg().getClass().getName().equals("model.InputDlg"),"register input");snapshot("04-register-name");input("TestUser");waitFor(()->dlg()!=null && dlg().getClass().getName().equals("model.MsgDlg"),"register guard");System.out.println("register guard: "+info(dlg()));snapshot("05-register-no-character");close(); } catch(Throwable e) { System.out.println("REGISTER_FAILED: "+e);e.printStackTrace();if(dlg()!=null)close(); }
        click(4);waitFor(()->cur()!=menu && cur().getClass().getName().equals("screen.SettingsScr"),"settings screen");snapshot("06-settings");Object settings=cur();Field select=settings.getClass().getDeclaredField("select");select.setAccessible(true);select.setInt(settings,1);act(settings,"center");waitFor(()->cur()==menu,"save settings returns to main");Class<?> prefs=midlet.getClass().getClassLoader().loadClass("com.teamobi.mobiarmy2.OfflineSettings");if(((Integer)prefs.getMethod("getFpsIndex").invoke(null)).intValue()!=1)throw new AssertionError("FPS setting not saved");System.out.println("SETTINGS_SAVE_PASS");
        try { click(2);Object pop=canvas.getField("menu").get(null);Thread.sleep(1200);if(!((Boolean)get(pop,"showMenu")))throw new AssertionError("Cloud menu not opened");snapshot("07-continue-no-save");pop.getClass().getField("showMenu").setBoolean(pop,false); } catch(Throwable e) {System.out.println("CONTINUE_FAILED: "+e);if(dlg()!=null){try {System.out.println("continue message: "+info(dlg()));}catch(Exception ignored){}snapshot("07-continue-error");close();} }
        click(3);waitFor(()->dlg()!=null,"new-game confirmation");snapshot("08-newgame-confirm");act(dlg(),"right");waitFor(()->dlg()==null,"cancel new game");
        click(3);waitFor(()->dlg()!=null,"new-game yes");act(dlg(),"left");waitFor(()->dlg()!=null && dlg().getClass().getName().equals("model.InputDlg"),"character name input");snapshot("09-new-character-name");
        if(display.getCurrent() instanceof TextBox){Object d=dlg();Object f=d.getClass().getField("tfInput").get(d);Method m=f.getClass().getDeclaredMethod("closeNativeTextBox");m.setAccessible(true);m.invoke(f);}
        input("TestHero");Thread.sleep(4000);snapshot("10-after-new-game");System.out.println("new game current screen: "+(cur()==null?"none":cur().getClass().getName()));if(dlg()!=null)System.out.println("new game dialog class: "+dlg().getClass().getName());
        Class<?> save=midlet.getClass().getClassLoader().loadClass("com.teamobi.mobiarmy2.OfflineSave");System.out.println("hasSave="+save.getMethod("hasSave").invoke(null));Class<?> terrain=midlet.getClass().getClassLoader().loadClass("coreLG.TerrainMidlet");Object profile=terrain.getField("myInfo").get(null);Field playerName=profile.getClass().getField("name");playerName.set(profile,"ChangedTemp");boolean loaded=((Boolean)save.getMethod("load").invoke(null)).booleanValue();Object restored=terrain.getField("myInfo").get(null);if(!loaded || !"TestHero".equals(restored.getClass().getField("name").get(restored)))throw new AssertionError("Offline save reload failed");System.out.println("SAVE_RELOAD_PASS");
        try {Object gameMenu=cur();Class<?> mc=gameMenu.getClass();act(gameMenu,"center");waitFor(()->mc.getField("curMenuLevel").getInt(null)==1,"start submenu");Thread.sleep(1200);snapshot("11-start-submenu");act(gameMenu,"center");waitFor(()->mc.getField("curMenuLevel").getInt(null)==2,"battle mode menu");Thread.sleep(1200);snapshot("12-battle-modes");act(gameMenu,"center");waitFor(()->cur()!=gameMenu,"boss room list");Thread.sleep(1200);snapshot("13-boss-list");System.out.println("BOSS_LIST_SCREEN="+cur().getClass().getName());Object bossList=cur();act(bossList,"center");Thread.sleep(3000);snapshot("14-boss-enter");System.out.println("BOSS_ENTER_SCREEN="+(cur()==null?"none":cur().getClass().getName()));if(dlg()!=null){System.out.println("BOSS_ENTER_DIALOG="+info(dlg()));if(dlg().getClass().getName().equals("model.InputDlg")){if(display.getCurrent() instanceof TextBox){Object inputField=dlg().getClass().getField("tfInput").get(dlg());Method m=inputField.getClass().getDeclaredMethod("closeNativeTextBox");m.setAccessible(true);m.invoke(inputField);}input("1");Thread.sleep(3000);snapshot("15-boss-ready");System.out.println("BOSS_READY_SCREEN="+cur().getClass().getName());if(cur().getClass().getName().equals("screen.PrepareScr")){Object cmd=get(cur(),"cmdStart");Object action=cmd.getClass().getField("action").get(cmd);Method perform=action.getClass().getMethod("perform");perform.setAccessible(true);perform.invoke(action);Thread.sleep(5000);snapshot("16-boss-battle");System.out.println("BOSS_BATTLE_SCREEN="+cur().getClass().getName());}}}}catch(Throwable e){System.out.println("OFFLINE_NAVIGATION_FAILED: "+e);e.printStackTrace();}
    }
}
